//! Export parity (ruby#493, the Rust-authoritative export): the Rust
//! lowering replays the Ruby-authoritative fixture byte-for-byte —
//! both the corpus artifacts and the hand-built convention cases
//! (escapes, \u class de-escaping, folds, bounded repetitions on both
//! targets, the expansion cap, every unsupported construct, the
//! recovery spine wrap, recursive-grammar rejection).
//!
//! The fixtures are generated by the Ruby `Parsanol::PARG::Export`
//! oracle; `tests/fixtures/export_parity/{corpus,synthetic}.json` are
//! its recorded outputs. The corpus half resolves artifact names
//! against `PARG_ARTIFACT_DIR` (the corpus-gate convention) and skips
//! with guidance when absent; the synthetic half ships its envelopes
//! inline and always asserts.

use parsanol::parg::export::{export_envelope, ExportTarget};
use serde_json::Value;

const CORPUS_FIXTURE: &str = include_str!("fixtures/export_parity/corpus.json");
const SYNTHETIC_FIXTURE: &str = include_str!("fixtures/export_parity/synthetic.json");

fn target(name: &str) -> ExportTarget {
    match name {
        "xgrammar" => ExportTarget::Xgrammar,
        "llguidance" => ExportTarget::Llguidance,
        other => panic!("unknown export target in the fixture: {other}"),
    }
}

fn replay(case: &Value, envelope: &Value) -> Result<String, String> {
    let parsed = match case["target"].as_str() {
        Some(name) => target(name),
        None => panic!("fixture case without a target: {case}"),
    };
    export_envelope(
        envelope,
        parsed,
        case["recovery"].as_bool().unwrap_or(false),
    )
    .map_err(|e| e.message)
}

fn assert_case(case: &Value, envelope: &Value) {
    let actual = replay(case, envelope);
    match (case.get("export"), case.get("error")) {
        (Some(expected), _) => {
            let expected = expected.as_str().expect("export is a string");
            assert_eq!(
                actual.as_deref(),
                Ok(expected),
                "{} ({}{}): exported bytes diverge from the Ruby oracle",
                case["artifact"].as_str().unwrap_or("?"),
                case["target"].as_str().unwrap_or("?"),
                if case["recovery"].as_bool().unwrap_or(false) {
                    " +recovery"
                } else {
                    ""
                },
            );
        }
        (_, Some(expected)) => {
            let expected = expected.as_str().expect("error is a string");
            assert_eq!(
                actual.err().as_deref(),
                Some(expected),
                "{} ({}{}): rejection message diverges from the Ruby oracle",
                case["artifact"].as_str().unwrap_or("?"),
                case["target"].as_str().unwrap_or("?"),
                if case["recovery"].as_bool().unwrap_or(false) {
                    " +recovery"
                } else {
                    ""
                },
            );
        }
        _ => panic!("fixture case carries neither export nor error: {case}"),
    }
}

/// The hand-built convention cases: self-contained, always asserted.
#[test]
fn synthetic_convention_cases_match_the_ruby_oracle_byte_for_byte() {
    let fixture: Value = serde_json::from_str(SYNTHETIC_FIXTURE).expect("synthetic fixture");
    let cases = fixture["cases"].as_array().expect("cases array");
    assert!(
        cases.len() >= 56,
        "the synthetic fixture shrank: {}",
        cases.len()
    );
    for case in cases {
        let envelope = &case["envelope"];
        assert!(envelope.is_object(), "case without an envelope: {case}");
        assert_case(case, envelope);
    }
}

/// The corpus artifacts: every corpus artifact × target × recovery
/// replayed byte-for-byte against the recorded oracle outputs. Requires
/// `PARG_ARTIFACT_DIR` (or an ambient sibling pubid-grammar checkout),
/// like the other corpus gates.
#[test]
fn corpus_artifacts_match_the_ruby_oracle_byte_for_byte() {
    let dir = match std::env::var("PARG_ARTIFACT_DIR") {
        Ok(dir) => std::path::PathBuf::from(dir),
        Err(_) => {
            let manifest = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
            match manifest
                .ancestors()
                .map(|ancestor| {
                    ancestor
                        .join("pubid")
                        .join("pubid-grammar")
                        .join("artifacts")
                })
                .find(|candidate| candidate.is_dir())
            {
                Some(dir) => dir,
                None => {
                    eprintln!("skip: no PARG_ARTIFACT_DIR and no sibling pubid-grammar checkout");
                    return;
                }
            }
        }
    };
    let fixture: Value = serde_json::from_str(CORPUS_FIXTURE).expect("corpus fixture");
    let cases = fixture["cases"].as_array().expect("cases array");
    assert!(
        cases.len() >= 90,
        "the corpus fixture shrank: {}",
        cases.len()
    );
    let mut checked = 0usize;
    let mut stale = std::collections::BTreeSet::new();
    for case in cases {
        let name = case["artifact"].as_str().expect("artifact name");
        let text = std::fs::read_to_string(dir.join(format!("{name}.json"))).unwrap_or_else(|e| {
            panic!(
                "corpus artifact {name}.json missing from {}: {e}",
                dir.display()
            )
        });
        // Each fixture case pins the sha256 of the artifact it was
        // recorded against: an owner re-bake moves the artifacts and
        // the case skips stale (the parg_corpus sibling philosophy) —
        // regenerate the fixture from the re-baked corpus to re-pin.
        let pinned = case["artifact_sha256"].as_str().expect("pinned sha");
        let actual = sha256_hex(text.as_bytes());
        if pinned != actual {
            stale.insert(name.to_string());
            continue;
        }
        // The corpus artifacts are verified loads (checksummed bakes);
        // a mid-re-bake sibling surfaces here as a verification error.
        let artifact = match parsanol::PargArtifact::from_json(&text) {
            Ok(artifact) => artifact,
            Err(e) => {
                eprintln!("skip: {name}.json does not verify against the current engine: {e}");
                continue;
            }
        };
        assert_case(case, artifact.envelope_value());
        checked += 1;
    }
    if !stale.is_empty() {
        eprintln!(
            "stale (re-baked since the fixture was recorded; regenerate fixtures/export_parity/corpus.json): {}",
            stale.into_iter().collect::<Vec<_>>().join(", ")
        );
    }
    assert!(
        checked >= 20,
        "corpus export parity checked only {checked} artifacts"
    );
    eprintln!("export parity: {checked} corpus artifacts × targets × recovery identical");
}

fn sha256_hex(bytes: &[u8]) -> String {
    use sha2::{Digest, Sha256};
    let digest = Sha256::digest(bytes);
    digest.iter().map(|b| format!("{b:02x}")).collect()
}
